<div class="relative flex flex-wrap items-center gap-2">
<label class="flex items-center gap-2 text-xs font-bold"><input type="checkbox" id="orders-select-all" aria-label="تحديد كل طلبات الصفحة" class="h-4 w-4 accent-black">تحديد كل طلبات الصفحة (<?= count($orders) ?>)</label><span class="text-xs font-bold" id="orders-selected-count">المحدد: 0</span><button type="button" id="export-selected" disabled class="rounded-full border bg-white px-4 py-2.5 text-xs font-bold disabled:opacity-40">تصدير المحدد (0)</button>
<button type="button" id="export-toggle" class="rounded-full bg-black px-5 py-2.5 text-sm font-bold text-white">تصدير الطلبات CSV</button>
<form id="orders-export-form" action="<?= e(admin_url('orders-export.php')) ?>" method="get" class="hidden fixed inset-x-4 top-20 z-30 max-h-[80vh] space-y-4 overflow-auto rounded-3xl border bg-white p-5 shadow-xl sm:absolute sm:inset-x-auto sm:left-0 sm:top-14 sm:w-[420px]">
<h2 id="export-title" class="font-bold">تصدير الطلبات</h2><p id="export-selected-note" class="hidden rounded-xl bg-sky-50 p-3 text-xs leading-6">سيتم تصدير الطلبات المحددة فقط، دون تطبيق فلاتر التاريخ أو الحالة. التحديد يخص الصفحة الحالية ويُمسح عند تغييرها.</p><div id="export-date-filters"><div class="grid grid-cols-2 gap-3"><label class="text-sm font-bold">من تاريخ<input aria-label="من تاريخ" type="date" name="from" class="mt-2 w-full min-w-0 rounded-xl border px-2 py-2"></label><label class="text-sm font-bold">إلى تاريخ<input aria-label="إلى تاريخ" type="date" name="to" class="mt-2 w-full min-w-0 rounded-xl border px-2 py-2"></label></div>
<label class="block text-sm font-bold">حالة الطلب<select aria-label="حالة الطلب" name="status" class="mt-2 w-full rounded-xl border p-2"><option value="">كل الحالات</option><?php foreach($valid as $v): ?><option value="<?= e($v) ?>" <?= $status===$v?'selected':'' ?>><?= e(order_status_label($v)) ?></option><?php endforeach; ?></select></label>
<p class="text-xs leading-6 text-neutral-500">CSV يفتح في Excel بالعربي. الفترة تشمل اليومين بتوقيت ليبيا. بدون تاريخ: كل الفترات. هذه الفلاتر مستقلة عن البحث وتقسيم الصفحات.</p></div>
<p class="rounded-xl bg-amber-50 p-3 text-xs leading-6 text-amber-900">صف لكل منتج. رسوم التوصيل والخصم والإجمالي تتكرر لكل طلب، لا تجمعها لكل صف. خصم الكوبون وخصم النقاط منفصلان. الاستيراد وخصم المخزون وإصدار الفواتير داخل منظومتك، لا ينفذها هذا الزر.</p>
<fieldset class="rounded-xl border p-3"><legend class="px-2 text-sm font-bold">الأعمدة <span id="export-count"></span></legend><div class="mb-3 flex gap-3 text-xs"><button type="button" data-columns="all">تحديد الكل</button><button type="button" data-columns="none">إلغاء الكل</button></div><div class="grid grid-cols-2 gap-3">
<?php foreach(json_decode(file_get_contents(APP_ROOT.'/includes/orders-export-columns.json'),true) as [$key,$label]): ?><label class="flex min-w-0 items-start gap-2 text-xs"><input type="checkbox" data-column value="<?= e($key) ?>" checked><span><?= e($label) ?><small class="mt-1 block break-all text-neutral-400" dir="ltr"><?= e($key) ?></small></span></label><?php endforeach; ?>
</div></fieldset><input type="hidden" name="columns"><p class="text-xs leading-6 text-neutral-500">الأسماء التقنية للأعمدة ثابتة، واختيارك محفوظ على هذا المتصفح. ملاحظات الإدارة خاصة. لا توجد حقول SKU أو حالة دفع أو مصدر الطلب أو آخر تعديل محفوظة حالياً، فلا يتم اختراعها.</p><p id="export-error" role="alert" class="text-sm text-red-700"></p><div class="sticky -bottom-5 -mx-5 border-t bg-white p-4 flex gap-2"><button id="export-download" class="rounded-full bg-black px-5 py-2.5 text-sm font-bold text-white disabled:opacity-50">تحميل CSV</button><button type="button" id="export-close" class="rounded-full border px-4 py-2 text-sm">إغلاق</button></div>
</form></div>
<script>
(()=>{let form=document.getElementById('orders-export-form'),checks=[...form.querySelectorAll('[data-column]')],error=document.getElementById('export-error'),btn=document.getElementById('export-download');
const sync=(save=true)=>{let selected=checks.filter(c=>c.checked).map(c=>c.value);form.elements.columns.value=selected.join(',');document.getElementById('export-count').textContent='('+selected.length+'/'+checks.length+')';if(save)try{localStorage.setItem('orders-export-columns-v1',JSON.stringify(selected));}catch{}};
try{let saved=JSON.parse(localStorage.getItem('orders-export-columns-v1')||'null');if(Array.isArray(saved)&&saved.length)checks.forEach(c=>c.checked=saved.includes(c.value));}catch{}sync(false);
checks.forEach(c=>c.onchange=()=>sync());form.querySelectorAll('[data-columns]').forEach(b=>b.onclick=()=>{checks.forEach(c=>c.checked=b.dataset.columns==='all');sync();});
let selectedMode=false,selected=[];const selectBtn=document.getElementById('export-selected'),all=document.getElementById('orders-select-all');
const setMode=selected=>{selectedMode=selected;document.getElementById('export-date-filters').hidden=selected;document.getElementById('export-selected-note').classList.toggle('hidden',!selected);document.getElementById('export-title').textContent=selected?'تصدير '+window.orderSelectedIds().length+' طلب محدد':'تصدير الطلبات';error.textContent='';};
window.orderSelectedIds=()=>[...new Set([...document.querySelectorAll('[data-order-id]:checked')].map(c=>c.dataset.orderId))];
const update=()=>{selected=window.orderSelectedIds();let total=new Set([...document.querySelectorAll('[data-order-id]')].map(c=>c.dataset.orderId)).size;all.checked=total>0&&selected.length===total;all.indeterminate=selected.length>0&&selected.length<total;selectBtn.disabled=!selected.length;selectBtn.textContent='تصدير المحدد ('+selected.length+')';document.getElementById('orders-selected-count').textContent='المحدد: '+selected.length;};
window.addEventListener('orders-selection',update);all.onchange=()=>{document.querySelectorAll('[data-order-id]').forEach(c=>c.checked=all.checked);update();};selectBtn.onclick=()=>{setMode(true);form.classList.remove('hidden');};
document.getElementById('export-toggle').onclick=()=>{setMode(false);form.classList.toggle('hidden');};document.getElementById('export-close').onclick=()=>form.classList.add('hidden');
form.onsubmit=async e=>{e.preventDefault();error.textContent='';if(!form.elements.columns.value){error.textContent='اختر عموداً واحداً على الأقل';return;}if(selectedMode&&!window.orderSelectedIds().length){error.textContent='حدد طلباً واحداً على الأقل';return;}if(!selectedMode&&form.elements.from.value&&form.elements.to.value&&form.elements.from.value>form.elements.to.value){error.textContent='تاريخ البداية يجب ألا يتجاوز النهاية';return;}btn.disabled=true;btn.textContent='جارٍ التصدير...';try{let params=new URLSearchParams(new FormData(form));if(selectedMode){params.delete('from');params.delete('to');params.delete('status');params.set('ids',window.orderSelectedIds().join(','));}let r=await fetch(form.action+'?'+params);if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'تعذر التصدير');}let blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='orders-export.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.textContent=e.message==='Failed to fetch'?'تعذر الاتصال. حاول مجدداً':e.message;}finally{btn.disabled=false;btn.textContent='تحميل CSV';}};
})();
</script>
